let user=null,users=[],managedUser='',banks=[],bankId='',templates=[],catalog={summary:{count:0,chapters:{}},tags:[]},learning={items:{},history:[]},attempt=null,adminTemplateId=null,pending=null,toastTimer,view='home',adminTab='banks',cardFilter='all',attemptsList=[],quizBusy=false,starting=false,saveTask=null,saveFailed=false,overlayReturn=null,cardReturn=null,bankLoadToken=0,importBankId='',reviewPage=0,bankLoading=false,failedBankId='',failedBankView='home',planBaseline='';
