async function api(path,method='GET',body){const response=await fetch(path,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(response.status===401){location.href='/login';throw Error('请先登录')}if(!response.ok)throw Error(data.error||`请求失败：${response.status}`);return data}
function toast(message){const box=$('toast');box.textContent=message;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3500)}
function show(name){if(user?.mustChangePassword)name='password';if(view==='admin'&&name!=='admin'&&planDirty())toast('方案草稿尚未保存，已为你保留');view=name;document.body.classList.toggle('is-answering',name==='quiz');$('accountMenu').open=false;if(name!=='quiz')closeCard();$('homeBtn').classList.toggle('active',name==='home');$('adminNav').classList.toggle('active',name==='admin');for(const part of ['home','admin','password','quiz','result'])$(part+'View').classList.toggle('hidden',part!==name);window.scrollTo(0,0)}
function modal(title,message,onConfirm,label='确定'){$('modalExtra').classList.add('hidden');$('modalExtra').replaceChildren();$('modalTitle').textContent=title;$('modalText').textContent=message;$('modalConfirm').textContent=label;pending=onConfirm;$('modalBackdrop').classList.remove('hidden');overlayReturn=document.activeElement;updateOverlay();$('modalCancel').focus({preventScroll:true})}
function updateOverlay(){document.body.classList.toggle('overlay-open',!$('modalBackdrop').classList.contains('hidden')||matchMedia('(max-width:850px)').matches&&$('cardPanel').classList.contains('open'))}
function openCard(){cardReturn=document.activeElement;$('cardPanel').classList.add('open');$('cardBackdrop').classList.remove('hidden');$('mobileCardBtn').setAttribute('aria-expanded','true');if(matchMedia('(max-width:850px)').matches){$('cardPanel').setAttribute('role','dialog');$('cardPanel').setAttribute('aria-modal','true');$('closeCardBtn').focus({preventScroll:true})}updateOverlay()}
