function updateSaveStatus(){if(!user)return;$('saveStatus').textContent=`${user.name} · ${saveFailed?'待重新保存':pendingProgress.size?'正在保存':'已同步'}`;$('saveStatus').classList.toggle('save-error',saveFailed);$('syncNotice').classList.toggle('hidden',!saveFailed)}
function queueProgress(body){const path=`/api/attempts/${attempt.id}/progress`,key=`${attempt.id}:${body.questionId}`;pendingProgress.set(key,{path,body});updateSaveStatus();flushProgress().catch(()=>{})}
async function flushProgress(){
  if(saveTask)return saveTask;
  if(!pendingProgress.size)return;
  saveTask=(async()=>{try{while(pendingProgress.size){const [key,change]=pendingProgress.entries().next().value;await api(change.path,'PATCH',change.body);if(pendingProgress.get(key)===change)pendingProgress.delete(key)}saveFailed=false;updateSaveStatus()}catch(error){saveFailed=true;updateSaveStatus();throw Error('答案尚未保存，请检查连接后重新保存。')}finally{saveTask=null}})();
  return saveTask;
}
function updateQuizControls(){if(!attempt||attempt.submittedAt)return;const q=current();for(const id of ['prevBtn','nextBtn','submitBtn','cardSubmitBtn','favoriteBtn','markBtn'])$(id).disabled=quizBusy;$('prevBtn').disabled=quizBusy||attempt.position===0;$('confirmBtn').disabled=quizBusy||!attempt.answers[q.id];$('options').querySelectorAll('button').forEach(button=>button.disabled=quizBusy||!!attempt.confirmed[q.id])}
async function quizAction(action){if(quizBusy)return;quizBusy=true;updateQuizControls();try{return await action()}finally{quizBusy=false;updateQuizControls()}}
function selectedBank(){return banks.find(b=>b.id===bankId)}
function selectedTemplate(){return templates.find(t=>t.id===$('templateSelect').value)}
function optionList(select,entries,firstLabel){select.innerHTML=firstLabel?`<option value="all">${escapeHtml(firstLabel)}</option>`:'';for(const [value,label] of entries)select.add(new Option(label,value))}
function rulesSummary(t){const count=TYPES.reduce((n,type)=>n+t.rules[type].count,0),score=TYPES.reduce((n,type)=>n+t.rules[type].count*t.rules[type].score,0);return `${count} 题 · 满分 ${Math.round(score*100)/100} 分 · ${t.chapters==='all'?'全部章节':t.chapters.join('、')}`}

function rememberedBank(){try{return localStorage.getItem('light-exam-bank')||''}catch{return ''}}
async function refreshBanks(preferred){preferred=preferred||rememberedBank();banks=await api('/api/banks');const target=banks.some(b=>b.id===preferred)?preferred:banks[0]?.id||'';optionList($('bankSelect'),banks.map(b=>[b.id,b.name]));optionList($('adminBankSelect'),banks.map(b=>[b.id,b.name]));await loadBank(target)}
async function loadBank(id){
 if(writeLocks.has('plan')&&id!==bankId)throw Error('方案正在保存，请稍候再切换题库');
 const token=++bankLoadToken,originView=view;bankLoading=true;failedBankId='';$('bankLoadNotice').classList.remove('hidden');$('bankLoadMessage').textContent='正在加载题库…';$('retryBankBtn').classList.add('hidden');updateScope();$('resumeBtn').disabled=true;$('resumeSelectedBtn').disabled=true;$('deleteAttemptBtn').disabled=true;$('deleteSelectedAttemptBtn').disabled=true;$('wrongShortcut').disabled=true;$('favoriteShortcut').disabled=true;
 try{
  await flushProgress();const b=banks.find(item=>item.id===id);
  const [t,c,l,a]=b?await Promise.all([api(`/api/banks/${id}/templates`),api(`/api/banks/${id}/catalog`),api(`/api/learning?bankId=${encodeURIComponent(id)}`),api('/api/attempts?unfinished=1')]):[[],{summary:{count:0,chapters:{}},tags:[],entries:[]},{items:{},history:[]},[]];
  const saved=a.find(v=>v.bankId===id),loaded=saved?await api(`/api/attempts/${saved.id}`):null;if(token!==bankLoadToken)return;
  if(id!==bankId){resetPlan();setEditor('plan',false)}bankId=b?id:'';templates=t;catalog=c;learning=l;attemptsList=a;attempt=loaded;
  $('bankSelect').value=bankId;$('adminBankSelect').value=bankId;try{localStorage.setItem('light-exam-bank',bankId)}catch{}if(attempt)activeAttempts.set(bankId,attempt);else activeAttempts.delete(bankId);
  optionList($('templateSelect'),t.map(v=>[v.id,v.name]));optionList($('chapterSelect'),Object.keys(c.summary.chapters).map(v=>[v,`${v}（${c.summary.chapters[v]}）`]),'全部章节');optionList($('tagSelect'),c.tags.map(v=>[v,v]),'全部标签');bankLoading=false;$('bankLoadNotice').classList.add('hidden');renderHome();renderAdmin();
 }catch(error){if(token!==bankLoadToken)return;failedBankId=id;failedBankView=originView;$('bankSelect').value=bankId;$('adminBankSelect').value=bankId;$('bankLoadMessage').textContent='题库加载失败，已保留原题库。请检查连接后重试。';$('retryBankBtn').classList.remove('hidden');throw error}
 finally{if(token===bankLoadToken){bankLoading=false;updateScope();$('resumeBtn').disabled=false;$('resumeSelectedBtn').disabled=false;$('deleteAttemptBtn').disabled=false;$('deleteSelectedAttemptBtn').disabled=false;$('wrongShortcut').disabled=!Object.values(learning.items).some(v=>v.wrong);$('favoriteShortcut').disabled=!Object.values(learning.items).some(v=>v.favorite)}}
}
function switchBank(id,destination='home'){if(writeLocks.has('plan'))return toast('方案正在保存，请稍候');const change=async()=>{await loadBank(id);if(destination==='admin')show('admin')};if(id!==bankId&&planDirty()){ $('bankSelect').value=bankId;$('adminBankSelect').value=bankId;modal('切换题库','当前方案有未保存的修改。切换成功后将放弃这份草稿。',async()=>{closeModal();await change()},'放弃草稿并切换');return}return change()}
function renderHome(){if(attempt?.submittedAt&&activeAttempts.has(bankId))attempt=activeAttempts.get(bankId);show('home');const b=selectedBank(),t=selectedTemplate();$('subjectTitle').textContent=b?.name||'选择题库';$('bankHint').textContent=b?`${b.count} 道题，可按章节练习`:'管理员创建题库并导入题目后即可答题';$('totalCount').textContent=b?.count||0;const items=Object.values(learning.items);$('wrongCount').textContent=items.filter(v=>v.wrong).length;$('favoriteCount').textContent=items.filter(v=>v.favorite).length;$('doneCount').textContent=items.reduce((n,v)=>n+v.answeredCount,0);$('wrongShortcut').disabled=!items.some(v=>v.wrong);$('favoriteShortcut').disabled=!items.some(v=>v.favorite);renderHistory();const exam=$('modeSelect').value==='exam';document.querySelectorAll('[data-mode]').forEach(button=>{const active=button.dataset.mode===$('modeSelect').value;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});$('templateField').classList.toggle('hidden',!exam);$('practiceFilters').classList.toggle('hidden',exam);$('templateSelect').disabled=!exam;renderTemplatePreview();updateScope();const resumable=attempt&&!attempt.submittedAt&&attempt.bankId===bankId;$('resumeAttempt').classList.toggle('hidden',!resumable);if(resumable)$('resumeDescription').textContent=`${attempt.mode==='exam'?'考试':'练习'} · ${attempt.title} · 第 ${attempt.position+1} / ${attempt.questions.length} 题`;buttonLabel('startBtn','arrow-right','开始答题',true);$('startBtn').onclick=()=>run(()=>start());$('resumeBtn').onclick=()=>{if(!bankLoading)renderQuiz()};renderUnfinished()}
function renderUnfinished(){const records=attemptsList.filter(a=>!a.submittedAt&&a.bankId===bankId);$('unfinishedRecords').classList.toggle('hidden',!records.length||(records.length===1&&attempt&&!attempt.submittedAt&&attempt.bankId===bankId));$('unfinishedCount').textContent=`未完成答题 · 共 ${records.length} 份`;optionList($('unfinishedSelect'),records.map(a=>[a.id,`${a.mode==='exam'?'考试':'练习'} · ${a.title} · ${new Date(a.createdAt).toLocaleString('zh-CN')} · 第 ${a.id===attempt?.id?attempt.position+1:(a.position||0)+1}/${a.questionCount||a.questions?.length||'?'} 题`]));if(records.some(a=>a.id===attempt?.id))$('unfinishedSelect').value=attempt.id}
function askDeleteAttempt(id){
 if(bankLoading||starting||!id||writeLocks.has('attempt-delete'))return;
 const record=attemptsList.find(a=>a.id===id)||(attempt?.id===id?attempt:null);
 if(!record||record.submittedAt)return;
 modal('删除未完成答题',`确定删除“${record.title}”？删除后无法继续这份答题。收藏、错题本和已交卷成绩会保留。`,()=>writeOnce('attempt-delete',['modalConfirm','modalCancel','deleteAttemptBtn','deleteSelectedAttemptBtn','resumeBtn','resumeSelectedBtn','startBtn','bankSelect','adminBankSelect'],async()=>{
   await flushProgress();
   await api(`/api/attempts/${id}`,'DELETE',{});
   attemptsList=attemptsList.filter(a=>a.id!==id);
   for(const [key,value] of activeAttempts)if(value.id===id)activeAttempts.delete(key);
   if(attempt?.id===id)attempt=null;
   closeModal();renderHome();toast('未完成答题已删除');
 }),'确认删除');
}
async function resumeSelected(){if(bankLoading)return;await writeOnce('resume',['resumeSelectedBtn','resumeBtn'],async()=>{await flushProgress();const loaded=await api(`/api/attempts/${$('unfinishedSelect').value}`);if(loaded.bankId!==bankId)throw Error('这份答题属于其他题库');attempt=loaded;if(!loaded.submittedAt)activeAttempts.set(bankId,loaded);renderQuiz()})}
function renderTemplatePreview(){const t=selectedTemplate();$('templateSummary').innerHTML=t?`<div class="plan-preview"><span>${escapeHtml(rulesSummary(t))}</span><div class="plan-rules">${TYPES.filter(type=>t.rules[type].count).map(type=>`<span>${type} ${t.rules[type].count} × ${t.rules[type].score}分</span>`).join('')}</div></div>`:'当前题库还没有考试方案。'}
function updateScope(){
 const b=selectedBank(),t=selectedTemplate(),exam=$('modeSelect').value==='exam';let canStart=false,help='',label='暂无题库';
 if(b&&exam){if(t){const missing=TYPES.filter(type=>t.rules[type].count>(catalog.summary.types?.[type]||0)).map(type=>`${type}缺少 ${t.rules[type].count-(catalog.summary.types?.[type]||0)} 题`);label=rulesSummary(t);canStart=!missing.length;help=missing.length?missing.join('，'):t.chapters==='all'?'从全部章节随机抽题，交卷后查看成绩。':'优先从指定章节抽题；数量不足时，从其他章节补齐。'}else label='请先配置考试方案'}
 if(b&&!exam){const chapter=$('chapterSelect').value,type=$('typeSelect').value,tag=$('tagSelect').value,source=$('sourceSelect').value;const count=(catalog.entries||[]).filter(q=>(chapter==='all'||q.chapter===chapter)&&(type==='all'||q.type===type)&&(tag==='all'||q.tags.includes(tag))&&(source==='all'||source==='wrong'&&learning.items[q.id]?.wrong||source==='favorite'&&learning.items[q.id]?.favorite)).length;label=`当前范围 ${count} 道题`;canStart=count>0;help=count?'确认答案后即可查看解析，题目顺序随机。':'当前筛选没有题目，可调整章节、题型或范围。'}
 const summary=[];if($('sourceSelect').value!=='all')summary.push($('sourceSelect').selectedOptions[0].textContent);if($('tagSelect').value!=='all')summary.push('标签：'+$('tagSelect').value);$('advancedFilterLabel').textContent=summary.length?'更多筛选 · '+summary.join(' · '):'更多筛选 · 范围与标签';$('clearAdvancedBtn').classList.toggle('hidden',exam||!summary.length);$('scopeCount').textContent=label;$('scopeHelp').textContent=help;$('scopeHelp').classList.toggle('scope-warning',!!b&&!canStart);$('startBtn').disabled=bankLoading||starting||!canStart;$('resetFiltersBtn').classList.toggle('hidden',exam||['chapterSelect','typeSelect','tagSelect','sourceSelect'].every(id=>$(id).value==='all'));
}
function renderHistory(){$('recentResult').innerHTML=learning.history.length?`<strong class="history-heading">最近考试</strong>${learning.history.slice(0,3).map(h=>`<button class="history-row" type="button" data-history="${escapeHtml(h.id)}"><span>${escapeHtml(h.title)}<small>${new Date(h.submitted_at).toLocaleDateString('zh-CN')}</small></span><strong>${h.score}<small> / ${h.max_score}</small> →</strong></button>`).join('')}`:'<span>完成首次考试后，这里可以回顾成绩。</span>';$('recentResult').querySelectorAll('[data-history]').forEach(button=>button.onclick=()=>run(async()=>{attempt=await api(`/api/attempts/${button.dataset.history}`);$('reviewFilter').value='all';renderResult()}))}
async function refreshLearning(){if(bankId)learning=await api(`/api/learning?bankId=${encodeURIComponent(bankId)}`);if(view==='home')renderHome()}
function adminRow(text,buttons){return `<div class="admin-row"><span>${escapeHtml(text)}</span><span class="row-actions">${buttons}</span></div>`}
function passwordIsStrong(value){return typeof value==='string'&&value.length>=8&&value.length<=128&&/[a-z]/.test(value)&&/[A-Z]/.test(value)&&/[0-9]/.test(value)}
function showPassword(required=user?.mustChangePassword){$('passwordTitle').textContent=required?'请修改初始密码':'修改密码';$('passwordHelp').textContent=required?'首次登录必须先设置新密码，之后才能使用题库。':'修改后其他设备需要重新登录。';$('currentPasswordField').classList.toggle('hidden',user?.authMethod==='oidc');$('currentPassword').required=user?.authMethod!=='oidc';$('passwordCancel').classList.toggle('hidden',!!required);$('passwordForm').reset();show('password')}
async function savePassword(event){event.preventDefault();const next=$('newPassword').value;if(next!==$('newPasswordConfirm').value)throw Error('两次输入的新密码不一致');if(!passwordIsStrong(next))throw Error('密码至少 8 位，且须包含大小写字母和数字');await api('/api/me/password','PATCH',{currentPassword:$('currentPassword').value,newPassword:next});const first=!!user.mustChangePassword;user.mustChangePassword=false;$('adminNav').classList.toggle('hidden',!user.canManage);$('passwordForm').reset();toast('密码已更新');if(first){await refreshBanks();if(user.canManage)await loadUsers()}else renderHome()}
async function loadUsers(){if(!user?.canManage)return;users=await api('/api/users');renderUsers()}
async function writeOnce(key,ids,action){if(writeLocks.has(key))return;writeLocks.add(key);const controls=ids.map(id=>typeof id==='string'?$(id):id).filter(Boolean).map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);const button=controls[0]?.el,html=button?.innerHTML;if(button)button.textContent='正在保存…';try{return await action()}finally{writeLocks.delete(key);controls.forEach(({el,disabled})=>el.disabled=disabled);if(button)button.innerHTML=html}}
