function setEditor(kind,open){const id=kind==='bank'?'bankCreateForm':kind+'Editor',trigger=kind==='bank'?'newBankBtn':kind==='plan'?'clearPlanBtn':'newUserBtn';$(id).classList.toggle('hidden',!open);$(trigger).setAttribute('aria-expanded',String(open));if(!open&&$(id).contains(document.activeElement))$(trigger).focus({preventScroll:true})}
function newPlan(){resetPlan();$('planEditorTitle').textContent='新建考试方案';$('planEditorContext').textContent=`所属题库：${selectedBank()?.name||'请先创建题库'}`;setEditor('plan',true);planBaseline=JSON.stringify(planBody());$('planName').focus()}
