async function saveUser(event){event.preventDefault();const username=$('managedUsername').value.trim(),password=$('managedPassword').value;if(password!==$('managedConfirm').value)throw Error('两次输入的密码不一致');if(!passwordIsStrong(password))throw Error('密码至少 8 位，且须包含大小写字母和数字');if(managedUser)await api(`/api/users/${encodeURIComponent(managedUser)}/password`,'PUT',{password});else await api('/api/users','POST',{username,password});toast(managedUser?'密码已重设':'用户已添加');resetUserForm();await loadUsers()}
function showAdminTab(name){
  if(!['banks','plans','users','access'].includes(name))return;
  adminTab=name;
  document.querySelectorAll('[data-admin-tab]').forEach(button=>{const active=button.dataset.adminTab===name;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});
  for(const section of ['banks','plans','users','access'])$('adminPanel-'+section).classList.toggle('hidden',section!==name);
}
function renderAdmin(){if(!user?.canManage)return;const chosenChapters=new Set([...$('planChapters').selectedOptions].map(o=>o.value));renderUsers();renderBankList();$('planChapters').innerHTML=Object.keys(catalog.summary.chapters).map(c=>`<option value="${escapeHtml(c)}" ${chosenChapters.has(c)?'selected':''}>${escapeHtml(c)}（${catalog.summary.chapters[c]}）</option>`).join('');$('planList').innerHTML=templates.map(t=>adminRow(`${t.name} · ${rulesSummary(t)}`,`<button data-action="edit" data-id="${t.id}">编辑</button><button data-action="remove" data-id="${t.id}" class="danger">停用</button>`)).join('')||'<p class="help-text">暂无考试方案</p>';updatePlanTotal();renderChapterPicker();showAdminTab(adminTab)}
async function loadAccessSettings(){accessSettings=await api('/api/settings/access');$('defaultAccessOrigin').textContent=accessSettings.defaultOrigin;$('defaultAccessOrigin').href=accessSettings.defaultOrigin;$('allowedOrigins').value=accessSettings.origins.join('\n');$('accessStatus').textContent=`已配置 ${accessSettings.origins.length} 个额外地址`}
async function saveAccessSettings(event){event.preventDefault();const origins=$('allowedOrigins').value.split(/\n/).map(value=>value.trim()).filter(Boolean);const save=()=>writeOnce('access',['saveAccessBtn','reloadAccessBtn','allowedOrigins'],async()=>{accessSettings=await api('/api/settings/access','PUT',{origins});$('allowedOrigins').value=accessSettings.origins.join('\n');$('accessStatus').textContent='已保存，访问设置立即生效，无需重启。';toast('访问设置已生效');closeModal()});const keepsCurrent=location.origin===accessSettings?.defaultOrigin||origins.some(value=>{try{return new URL(value).origin===location.origin}catch{return false}});if(!keepsCurrent){modal('移除当前访问地址','保存后，当前地址将不能继续提交登录和操作请求。请改用上方的默认地址登录。',save,'确认移除并保存');return}await save()}
function renderBankList(){const search=$('bankSearch').value.trim().toLocaleLowerCase(),visible=banks.filter(b=>b.name.toLocaleLowerCase().includes(search));$('currentBankHint').textContent=`当前题库：${selectedBank()?.name||'暂无'} · 共 ${banks.length} 个题库`;$('adminBanks').innerHTML=visible.map(b=>`<div class="admin-row bank-row ${b.id===bankId?'is-current':''}"><span><strong>${escapeHtml(b.name)}</strong><small>${b.count} 题${b.id===bankId?' · 当前题库':''}</small></span><span class="row-actions"><button data-action="questions" data-id="${b.id}" ${b.count?'':'disabled'}>编辑题目</button><button data-action="import" data-id="${b.id}">${icon('upload')}导入题目</button><button data-action="export" data-id="${b.id}" ${b.count?'':'disabled'}>${icon('download')}导出</button><button data-action="select" data-id="${b.id}" ${b.id===bankId?'disabled':''}>${b.id===bankId?'已选择':'选择'}</button><button data-action="rename" data-id="${b.id}">改名</button><button data-action="remove" data-id="${b.id}" class="danger">停用</button></span></div>`).join('')||'<p class="help-text">没有匹配的题库。</p>'}
function renderChapterPicker(){const all=$('allChapters').checked;$('chapterPicker').classList.toggle('hidden',all);$('chapterHelp').textContent=all?'从全部章节抽题。':'点选指定章节；题量不足时，从其他章节补齐。';$('chapterPicker').innerHTML=[...$('planChapters').options].map(o=>`<label class="chapter-choice"><input type="checkbox" value="${escapeHtml(o.value)}" ${o.selected?'checked':''} ${all?'disabled':''}><span>${escapeHtml(o.textContent)}</span></label>`).join('')||'<span class="help-text">导入题目后可选择章节。</span>';$('chapterPicker').querySelectorAll('input').forEach(input=>input.onchange=()=>{for(const o of $('planChapters').options)if(o.value===input.value)o.selected=input.checked})}
function resetPlan(){adminTemplateId=null;$('planName').value='';$('allChapters').checked=true;for(const o of $('planChapters').options)o.selected=false;for(const id of ['singleCount','multipleCount','judgmentCount'])$(id).value='0';$('singleScore').value='0.5';$('multipleScore').value='2';$('judgmentScore').value='1';updatePlanTotal();renderChapterPicker();planBaseline=JSON.stringify(planBody())}
function updatePlanTotal(){const count=['singleCount','multipleCount','judgmentCount'].map(id=>Number($(id).value)||0),score=['singleScore','multipleScore','judgmentScore'].map(id=>Number($(id).value)||0);$('planTotal').textContent=`共 ${count.reduce((a,b)=>a+b,0)} 题 · 满分 ${Math.round(count.reduce((n,v,i)=>n+v*score[i],0)*100)/100} 分`}
function planBody(){return{name:$('planName').value.trim(),chapters:$('allChapters').checked?'all':[...$('planChapters').selectedOptions].map(o=>o.value),rules:{单选:{count:Number($('singleCount').value),score:Number($('singleScore').value)},多选:{count:Number($('multipleCount').value),score:Number($('multipleScore').value)},判断:{count:Number($('judgmentCount').value),score:Number($('judgmentScore').value)}}}}
async function savePlan(){return writeOnce('plan',['savePlanBtn','clearPlanBtn','cancelPlanBtn','adminBankSelect','bankSelect',...$('planEditor').querySelectorAll('input,select')],async()=>{if(!bankId)throw Error('请先创建题库');const target=bankId,body=planBody(),path=adminTemplateId?`/api/templates/${adminTemplateId}`:`/api/banks/${target}/templates`;await api(path,adminTemplateId?'PUT':'POST',body);toast('考试方案已保存');resetPlan();setEditor('plan',false);await loadBank(target);show('admin')})}
function editPlan(id){const t=templates.find(v=>v.id===id);if(!t)return;setEditor('plan',true);$('planEditorTitle').textContent=`编辑方案：${t.name}`;$('planEditorContext').textContent=`所属题库：${selectedBank()?.name||''}`;adminTemplateId=id;$('planName').value=t.name;$('allChapters').checked=t.chapters==='all';for(const o of $('planChapters').options)o.selected=t.chapters!=='all'&&t.chapters.includes(o.value);for(const [type,prefix] of [['单选','single'],['多选','multiple'],['判断','judgment']]){$(prefix+'Count').value=t.rules[type].count;$(prefix+'Score').value=t.rules[type].score}updatePlanTotal();renderChapterPicker();planBaseline=JSON.stringify(planBody());$('planName').focus()}

async function start(mode=$('modeSelect').value,extra={}){if(!bankId||starting||bankLoading)return;starting=true;$('startBtn').disabled=true;try{await flushProgress();const body={bankId,mode};if(mode==='exam')body.templateId=$('templateSelect').value;else body.filters={chapter:$('chapterSelect').value,type:$('typeSelect').value,tag:$('tagSelect').value,source:$('sourceSelect').value,...extra};attempt=await api('/api/attempts','POST',body);activeAttempts.set(bankId,attempt);attemptsList.unshift({...attempt,questionCount:attempt.questions.length});cardFilter='all';renderQuiz()}finally{starting=false;if(view==='home')renderHome()}}
const current=()=>attempt.questions[attempt.position];
function renderQuiz(){if(!attempt)return renderHome();if(attempt.submittedAt)return renderResult();const q=current();show('quiz');closeCard();const key=attempt.id+':'+q.id;if(renderedQuestionKey!==key){$('questionScroll').scrollTop=0;renderedQuestionKey=key}$('modeBadge').textContent=attempt.mode==='exam'?'考试模式':'练习模式';$('quizTitle').textContent=attempt.title;$('quizTitle').title=attempt.title;$('quizProgress').textContent=`${attempt.position+1} / ${attempt.questions.length}`;$('questionType').textContent=q.type+'题';$('questionNumber').textContent=`第 ${attempt.position+1} 题`;$('questionNumber').title=`原题号 ${q.number}`;$('questionChapter').textContent=q.chapter;$('questionStem').textContent=q.stem;$('answerHint').textContent=q.type==='多选'?'请选择所有正确答案，全部选对才算正确。':'请选择一个答案。';const favorite=!!learning.items[q.id]?.favorite;buttonLabel('favoriteBtn','star',favorite?'已收藏':'收藏');$('favoriteBtn').classList.toggle('active',favorite);buttonLabel('markBtn','flag',attempt.marks[q.id]?'已标记':'标记');$('markBtn').classList.toggle('active',!!attempt.marks[q.id]);const chosen=attempt.answers[q.id]||'',confirmed=!!attempt.confirmed[q.id];renderSelectionStatus();$('options').innerHTML=Object.entries(q.options).map(([letter,label])=>`<button type="button" class="option ${chosen.includes(letter)?'selected':''} ${confirmed&&q.answer?.includes(letter)?'correct':''} ${confirmed&&chosen.includes(letter)&&!q.answer?.includes(letter)?'incorrect':''}" data-letter="${letter}" aria-pressed="${chosen.includes(letter)}" ${confirmed?'disabled':''}><span class="letter">${letter}</span><span>${escapeHtml(label)}</span></button>`).join('');$('options').querySelectorAll('button').forEach(button=>button.onclick=()=>choose(button.dataset.letter));$('feedback').classList.toggle('hidden',!confirmed);if(confirmed){$('feedback').classList.toggle('wrong',chosen!==q.answer);$('feedback').innerHTML=`<strong>${chosen===q.answer?'回答正确':'回答错误'} · 正确答案 ${escapeHtml(q.answer)}</strong>${escapeHtml(q.explanation||'原题未提供解析。')}`}$('confirmBtn').classList.toggle('hidden',attempt.mode==='exam'||confirmed);$('confirmBtn').disabled=!chosen;$('prevBtn').disabled=attempt.position===0;buttonLabel('nextBtn',attempt.position===attempt.questions.length-1?'grid':'arrow-right',attempt.position===attempt.questions.length-1?'查看答题卡':'下一题',true);renderCard();updateQuizControls()}
async function choose(letter){const q=current();if(quizBusy||attempt.confirmed[q.id]||!Object.hasOwn(q.options,letter))return;const previous=attempt.answers[q.id]||'',answer=q.type==='多选'?normalizeAnswer(previous.includes(letter)?previous.replace(letter,''):previous+letter):letter;attempt.answers[q.id]=answer;$('options').querySelectorAll('.option').forEach(button=>{const active=answer.includes(button.dataset.letter);button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});$('confirmBtn').disabled=!answer;renderSelectionStatus();renderCard();queueProgress({questionId:q.id,answer,position:attempt.position,marked:!!attempt.marks[q.id]})}
async function confirmQuestion(){return quizAction(async()=>{await flushProgress();const q=current();if(!attempt.answers[q.id])return;const result=await api(`/api/attempts/${attempt.id}/confirm`,'POST',{questionId:q.id});attempt.confirmed[q.id]=true;attempt.questions[attempt.position]={...q,answer:result.answer,explanation:result.explanation};await refreshLearning();renderQuiz()})}
async function moveTo(index){return quizAction(async()=>{await flushProgress();const position=Math.max(0,Math.min(attempt.questions.length-1,index));await api(`/api/attempts/${attempt.id}/position`,'PATCH',{position});attempt.position=position;renderQuiz();requestAnimationFrame(()=>window.scrollTo({top:Math.max(0,$('quizView').offsetTop-10),behavior:'auto'}))})}
function renderSelectionStatus(){const q=current(),answer=attempt.answers[q.id]||'';$('selectionStatus').textContent=answer?`已选择 ${[...answer].join('、')}${attempt.confirmed[q.id]?' · 已确认':attempt.mode==='practice'?' · 确认后查看解析':''}`:'尚未选择答案'}
function renderCard(){
  const n=attempt.questions.filter(q=>attempt.answers[q.id]).length,m=attempt.questions.filter(q=>attempt.marks[q.id]).length;
  $('cardAnswered').textContent=n;$('cardUnanswered').textContent=attempt.questions.length-n;$('cardMarked').textContent=m;
  $('mobileCount').textContent=`${n}/${attempt.questions.length}`;
  const progress=Math.round(n/attempt.questions.length*100);$('answerProgress').setAttribute('aria-valuenow',String(progress));$('answerProgressFill').style.width=progress+'%';
  $('jumpNumber').max=attempt.questions.length;$('nextBlankBtn').disabled=n===attempt.questions.length;
  document.querySelectorAll('[data-card-filter]').forEach(button=>{const active=button.dataset.cardFilter===cardFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});
  const groups=TYPES.map(type=>{const qs=attempt.questions.map((q,i)=>({q,i})).filter(({q})=>q.type===type&&(cardFilter==='all'||cardFilter==='blank'&&!attempt.answers[q.id]||cardFilter==='marked'&&attempt.marks[q.id]));return qs.length?`<div class="card-group"><h3>${type}题 · ${qs.length} 题</h3><div class="card-grid">${qs.map(({q,i})=>`<button type="button" class="card-cell ${attempt.answers[q.id]?'answered':''} ${attempt.marks[q.id]?'marked':''} ${i===attempt.position?'current':''}" data-index="${i}" ${i===attempt.position?'aria-current="step"':''} aria-label="第 ${i+1} 题，${attempt.answers[q.id]?'已答':'未答'}${attempt.marks[q.id]?'，已标记':''}">${i+1}</button>`).join('')}</div></div>`:''}).join('');
  $('cardGroups').innerHTML=groups||'<p class="empty-state">没有符合条件的题目。</p>';
  $('cardGroups').querySelectorAll('button').forEach(button=>button.onclick=()=>run(()=>moveTo(Number(button.dataset.index))));
}
async function nextBlank(){const size=attempt.questions.length;for(let step=1;step<=size;step++){const index=(attempt.position+step)%size;if(!attempt.answers[attempt.questions[index].id])return moveTo(index)}}
async function toggleFavorite(){const q=current(),state=await api(`/api/questions/${q.id}/favorite`,'POST',{});learning.items[q.id]??={favorite:false,wrong:false,answeredCount:0};learning.items[q.id].favorite=state.favorite;buttonLabel('favoriteBtn','star',state.favorite?'已收藏':'收藏');$('favoriteBtn').classList.toggle('active',state.favorite)}
async function toggleMark(){if(quizBusy)return;const q=current(),marked=!attempt.marks[q.id];attempt.marks[q.id]=marked;buttonLabel('markBtn','flag',marked?'已标记':'标记');$('markBtn').classList.toggle('active',marked);renderCard();queueProgress({questionId:q.id,answer:attempt.answers[q.id]||'',position:attempt.position,marked})}
function askSubmit(){const blank=attempt.questions.filter(q=>!attempt.answers[q.id]).length,marked=attempt.questions.filter(q=>attempt.marks[q.id]).length;modal('确认交卷',`本次共 ${attempt.questions.length} 题，未作答 ${blank} 题，标记 ${marked} 题。交卷后显示成绩与解析。`,async()=>quizAction(async()=>{await flushProgress();attempt=await api(`/api/attempts/${attempt.id}/submit`,'POST',{});activeAttempts.delete(bankId);attemptsList=attemptsList.filter(a=>a.id!==attempt.id);closeModal();await refreshLearning();renderResult()}),'确认交卷');if(blank){$('modalExtra').classList.remove('hidden');const button=document.createElement('button');button.type='button';button.className='secondary-button wide';button.textContent=`先检查 ${blank} 道未答题 →`;button.onclick=()=>run(async()=>{closeModal();await nextBlank()});$('modalExtra').append(button)}}
function renderResult(){show('result');reviewPage=0;const s=attempt.stats;$('resultTitle').textContent=attempt.mode==='exam'?'考试成绩':'练习完成';$('resultMessage').textContent=`${attempt.questions.length} 道题 · ${attempt.title}`;$('scoreValue').textContent=s.score;$('maxScoreValue').textContent=`满分 ${s.maxScore} 分`;$('correctValue').textContent=s.correct;$('incorrectValue').textContent=s.incorrect;$('blankValue').textContent=s.blank;$('retryWrongBtn').disabled=!attempt.questions.some(q=>attempt.answers[q.id]!==q.answer);$('resultBreakdown').innerHTML=TYPES.filter(type=>attempt.questions.some(q=>q.type===type)).map(type=>{const qs=attempt.questions.filter(q=>q.type===type),good=qs.filter(q=>attempt.answers[q.id]===q.answer).length;return `<span>${type}题 <strong>${good} / ${qs.length}</strong> 正确</span>`}).join('');renderReviews()}
function renderReviews(){
 const filter=$('reviewFilter').value;const qs=attempt.questions.map((q,i)=>({q,i})).filter(({q})=>filter==='all'||filter==='wrong'&&attempt.answers[q.id]&&attempt.answers[q.id]!==q.answer||filter==='blank'&&!attempt.answers[q.id]||filter==='correct'&&attempt.answers[q.id]===q.answer);
 const pages=Math.max(1,Math.ceil(qs.length/REVIEW_PAGE_SIZE));reviewPage=Math.max(0,Math.min(reviewPage,pages-1));const offset=reviewPage*REVIEW_PAGE_SIZE;$('reviewCount').textContent=qs.length?`共 ${qs.length} 题 · 显示第 ${offset+1}–${Math.min(offset+REVIEW_PAGE_SIZE,qs.length)} 题`: '当前筛选下没有题目';$('reviewPageLabel').textContent=`第 ${reviewPage+1} / ${pages} 页`;$('reviewPrevBtn').disabled=reviewPage===0;$('reviewNextBtn').disabled=reviewPage>=pages-1;$('reviewPager').classList.toggle('hidden',pages<=1);$('reviewList').innerHTML=qs.length?qs.slice(offset,offset+REVIEW_PAGE_SIZE).map(({q,i})=>{const a=attempt.answers[q.id]||'',kind=!a?'blank':a===q.answer?'good':'bad';return `<details class="review-item panel"><summary><span class="review-top"><span>第 ${i+1} 题 · ${q.type}题 · ${escapeHtml(q.chapter)}</span><span class="review-status ${kind}">${kind==='good'?'✓ 正确':kind==='bad'?'× 错误':'○ 未答'}</span></span><span class="review-stem">${escapeHtml(q.stem)}</span><span class="review-toggle">展开 / 收起答案与解析</span></summary><div class="review-options">${Object.entries(q.options).map(([letter,label])=>`<div class="review-option ${q.answer.includes(letter)?'is-correct':a.includes(letter)?'is-incorrect':''}"><b>${letter}</b><span>${escapeHtml(label)}</span><small>${q.answer.includes(letter)?'✓ 正确答案':a.includes(letter)?'× 你的选择':''}</small></div>`).join('')}</div><p class="review-answer">你的答案：${escapeHtml(a||'未作答')}　正确答案：${escapeHtml(q.answer)}</p><div class="review-explanation"><strong>试题解析</strong><p>${escapeHtml(q.explanation||'原题未提供解析。')}</p></div></details>`}).join(''):'<div class="review-item panel empty-state">当前筛选下没有题目。</div>';
}
async function retryWrong(){const ids=attempt.questions.filter(q=>attempt.answers[q.id]!==q.answer).map(q=>q.id);if(!ids.length)return;await start('practice',{ids,chapter:'all',type:'all',tag:'all',source:'all'})}

function parseCsv(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','||c==='\t'){row.push(field);field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>String(x).trim()))rows.push(row);row=[];field=''}else field+=c}row.push(field);if(row.some(x=>String(x).trim()))rows.push(row);return rows}
function fromTable(rows){if(rows.length<2)throw Error('表格没有题目');const heads=rows[0].map(v=>String(v).trim().replace(/\s/g,'').toLowerCase()),col=(...names)=>heads.findIndex(h=>names.includes(h)),get=(row,...names)=>{const i=col(...names);return i<0?'':String(row[i]??'').trim()};if(col('题干','题目','question','stem')<0)throw Error('缺少“题干”列');return rows.slice(1).filter(row=>row.some(v=>String(v).trim())).map((row,i)=>{const options={};for(const c of 'ABCDEFGH'){const v=get(row,'选项'+c.toLowerCase(),c.toLowerCase());if(v)options[c]=v}const rawTags=get(row,'标签','tags');let tags=rawTags;if(rawTags.startsWith('[')){try{const parsed=JSON.parse(rawTags);if(Array.isArray(parsed)&&parsed.every(v=>typeof v==='string'))tags=parsed}catch{}}const chapter=get(row,'章节','chapter');if(chapter){tags=Array.isArray(tags)?tags:String(tags).split(/[,，;；|\n]/).map(v=>v.trim()).filter(Boolean);if(!tags.some(v=>/^章节[:：]/.test(v)))tags.push('章节:'+chapter)}return{number:get(row,'序号','题号','id')||i+1,stem:get(row,'题干','题目','question','stem'),options,answer:get(row,'答案','正确答案','answer'),explanation:get(row,'解析','试题解析','explanation'),type:get(row,'题型','type'),tags}})}
function fromJson(data){const rows=Array.isArray(data)?data:data?.questions;if(!Array.isArray(rows))throw Error('JSON 应为题目数组或含 questions 数组的对象');return rows}
async function importFile(file,targetId){const target=banks.find(b=>b.id===targetId);if(!file||!target)return;let rows;if(/\.json$/i.test(file.name))rows=fromJson(JSON.parse(await file.text()));else if(/\.csv$/i.test(file.name))rows=fromTable(parseCsv(await file.text()));else if(/\.xlsx$/i.test(file.name))rows=fromTable(await parseXlsx(await file.arrayBuffer()));else throw Error('请选择 XLSX、CSV 或 JSON 文件');const summary=await api('/api/import/preview','POST',{questions:rows});const details=Object.entries(summary.chapters).map(([c,n])=>`${c} ${n} 题`).join('、');const warning=summary.uncategorized?`\n其中 ${summary.uncategorized} 题未标注章节。`:'';modal('确认导入',`识别 ${summary.count} 道题（单选 ${summary.types.单选}、多选 ${summary.types.多选}、判断 ${summary.types.判断}）。\n章节：${details}${warning}\n将替换“${target.name}”的现有题目。`,async()=>{await api(`/api/banks/${targetId}/questions`,'PUT',{questions:rows});closeModal();toast('题库导入完成');await refreshBanks(targetId);show('admin')},'确认替换')}
function saveDownload(data,type,name){const url=URL.createObjectURL(new Blob([data],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function csvCell(value){let text=String(value??'');if(/^[=+\-@]/.test(text))text='\t'+text;return '"'+text.replaceAll('"','""')+'"'}
async function exportBank(target,format){const source=await api(`/api/banks/${target.id}/questions`);if(!source.length)throw Error('此题库暂无题目');const rows=source.map(q=>({number:q.number,type:q.type,stem:q.stem,options:q.options,answer:q.answer,explanation:q.explanation,tags:[...q.tags,...(q.chapter==='未分类'?[]:['章节:'+q.chapter])]}));const date=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),safe=Array.from(target.name.replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_')).slice(0,60).join('')||'题库',name=`${safe}-${date}.${format}`;
 if(format==='json')saveDownload(JSON.stringify({format:'light-exam',version:1,bank:{name:target.name},questions:rows},null,2),'application/json;charset=utf-8',name);
 else{const headers=['序号','题型','题干',...'ABCDEFGH'.split('').map(c=>'选项 '+c),'答案','解析','章节','标签'];const table=source.map(q=>[q.number,q.type,q.stem,...'ABCDEFGH'.split('').map(c=>q.options[c]||''),q.answer,q.explanation,q.chapter,JSON.stringify(q.tags)]);saveDownload('\ufeff'+[headers,...table].map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8',name)}closeModal();toast(`已导出 ${rows.length} 道题`)}
