async function parseXlsx(buffer){const bytes=new Uint8Array(buffer),files={};let eocd=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(read32(bytes,i)===0x06054b50){eocd=i;break}if(eocd<0)throw Error('不是有效的 XLSX 文件');const view=new DataView(buffer),count=view.getUint16(eocd+10,true),offset=view.getUint32(eocd+16,true);let p=offset;for(let i=0;i<count;i++){if(read32(bytes,p)!==0x02014b50)throw Error('XLSX 压缩目录损坏');const method=view.getUint16(p+10,true),size=view.getUint32(p+20,true),nameLen=view.getUint16(p+28,true),extra=view.getUint16(p+30,true),comment=view.getUint16(p+32,true),local=view.getUint32(p+42,true),name=new TextDecoder().decode(bytes.slice(p+46,p+46+nameLen));const dataStart=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true);if(name==='xl/sharedStrings.xml'||name==='xl/worksheets/sheet1.xml'){const chunk=bytes.slice(dataStart,dataStart+size);let data;if(method===0)data=chunk;else if(method===8){if(typeof DecompressionStream==='undefined')throw Error('此浏览器不支持 XLSX 解压，请使用 CSV');const stream=new Blob([chunk]).stream().pipeThrough(new DecompressionStream('deflate-raw'));data=new Uint8Array(await new Response(stream).arrayBuffer())}else throw Error('不支持的 XLSX 压缩格式');files[name]=new TextDecoder().decode(data)}p+=46+nameLen+extra+comment}if(!files['xl/worksheets/sheet1.xml'])throw Error('找不到第一个工作表');const xml=s=>new DOMParser().parseFromString(s,'application/xml'),shared=files['xl/sharedStrings.xml']?[...xml(files['xl/sharedStrings.xml']).getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];const sheet=xml(files['xl/worksheets/sheet1.xml']),rows=[];for(const row of sheet.getElementsByTagName('row')){let vals=[];for(const cell of row.getElementsByTagName('c')){let ref=cell.getAttribute('r')||'',letters=ref.match(/^[A-Z]+/)?.[0]||'A',index=0;for(const c of letters)index=index*26+c.charCodeAt(0)-64;index--;const value=cell.getElementsByTagName('v')[0]?.textContent??[...cell.getElementsByTagName('t')].map(t=>t.textContent).join('');vals[index]=cell.getAttribute('t')==='s'?shared[Number(value)]??'':value}rows.push(vals)}return rows}
function read32(b,p){return (b[p]|b[p+1]<<8|b[p+2]<<16|b[p+3]<<24)>>>0}
